/* Generated by Dudaport: the few behaviours Duda's runtime provided that migrated pages still need.
   - Sticky headers: Duda's CSS styles a header with [data-scrollable-target] by the scroll-responder_set class once the
     page scrolls past data-scrollable-target-threshold (e.g. a transparent header over the hero that turns solid).
   - Carousels: [data-lsw-carousel] (Dudaport's reviews widget): arrows, dots, autoplay, swipe via native scrolling.
   - Radius maps: [data-lsw-map] (Dudaport's map widget): Google Map with a marker and a service-radius circle. */
(function () {
  'use strict';

  function stickyHeaders() {
    var headers = Array.prototype.slice.call(document.querySelectorAll('[data-scrollable-target]'));
    if (!headers.length) return;
    function update() {
      var y = window.pageYOffset || document.documentElement.scrollTop || 0;
      headers.forEach(function (h) {
        var threshold = parseInt(h.getAttribute('data-scrollable-target-threshold') || '1', 10) || 1;
        h.classList.toggle('scroll-responder_set', y >= threshold);
      });
    }
    window.addEventListener('scroll', update, { passive: true });
    update();
  }

  function carousel(viewport) {
    var track = viewport.querySelector('.lsw-track');
    if (!track) return;
    var slides = Array.prototype.slice.call(track.children);
    if (slides.length < 2) return;
    var autoplay = viewport.getAttribute('data-autoplay') === 'true';
    var speed = Math.max(1500, parseInt(viewport.getAttribute('data-speed') || '3000', 10) || 3000);
    var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var dotsWrap = null, timer = null, paused = false;

    function perView() {
      var w = slides[0].getBoundingClientRect().width || 1;
      return Math.max(1, Math.round(track.clientWidth / w));
    }
    function pages() { return Math.max(1, slides.length - perView() + 1); }
    function current() {
      var w = slides[0].getBoundingClientRect().width || 1;
      return Math.round(track.scrollLeft / w);
    }
    function go(i) {
      var n = pages();
      i = ((i % n) + n) % n;
      track.scrollTo({ left: slides[i].offsetLeft - track.offsetLeft, behavior: reduced ? 'auto' : 'smooth' });
    }
    function button(cls, label, text, fn) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = cls; b.setAttribute('aria-label', label); b.textContent = text;
      b.addEventListener('click', function () { fn(); restart(); });
      return b;
    }
    if (viewport.getAttribute('data-arrows') !== 'false') {
      viewport.appendChild(button('lsw-prev', 'Previous', '‹', function () { go(current() - 1); }));
      viewport.appendChild(button('lsw-next', 'Next', '›', function () { go(current() + 1); }));
    }
    function renderDots() {
      if (viewport.getAttribute('data-dots') === 'false') return;
      if (!dotsWrap) {
        dotsWrap = document.createElement('div');
        dotsWrap.className = 'lsw-dots';
        viewport.parentNode.insertBefore(dotsWrap, viewport.nextSibling);
      }
      var n = pages(), cur = Math.min(current(), n - 1);
      if (dotsWrap.children.length !== n) {
        dotsWrap.innerHTML = '';
        for (var i = 0; i < n; i++) {
          (function (k) {
            dotsWrap.appendChild(button('lsw-dot', 'Go to slide ' + (k + 1), '', function () { go(k); }));
          })(i);
        }
      }
      Array.prototype.forEach.call(dotsWrap.children, function (d, k) { d.setAttribute('aria-current', k === cur ? 'true' : 'false'); });
    }
    function restart() {
      if (timer) clearInterval(timer);
      timer = null;
      if (autoplay && !reduced) timer = setInterval(function () { if (!paused && !document.hidden) go(current() + 1); }, speed);
    }
    ['mouseenter', 'focusin', 'touchstart'].forEach(function (e) { viewport.addEventListener(e, function () { paused = true; }, { passive: true }); });
    ['mouseleave', 'focusout', 'touchend'].forEach(function (e) { viewport.addEventListener(e, function () { paused = false; }, { passive: true }); });
    var t = null;
    track.addEventListener('scroll', function () { clearTimeout(t); t = setTimeout(renderDots, 80); }, { passive: true });
    window.addEventListener('resize', renderDots);
    renderDots();
    restart();
  }

  function maps() {
    var els = Array.prototype.slice.call(document.querySelectorAll('[data-lsw-map]'));
    if (!els.length) return;
    window.lswInitMaps = function () {
      els.forEach(function (el) {
        var center = { lat: parseFloat(el.getAttribute('data-lat')), lng: parseFloat(el.getAttribute('data-lng')) };
        if (isNaN(center.lat) || isNaN(center.lng)) return;
        var map = new google.maps.Map(el, { center: center, zoom: parseInt(el.getAttribute('data-zoom') || '10', 10) });
        var marker = { position: center, map: map };
        if (el.getAttribute('data-marker')) marker.icon = el.getAttribute('data-marker');
        new google.maps.Marker(marker);
        var radius = parseFloat(el.getAttribute('data-radius-m') || '');
        if (radius > 0) {
          var color = el.getAttribute('data-color') || '#aa1010';
          new google.maps.Circle({ map: map, center: center, radius: radius, strokeColor: color, strokeOpacity: 0.8,
                                   strokeWeight: 2, fillColor: color, fillOpacity: 0.2 });
        }
      });
    };
    var s = document.createElement('script');
    s.src = 'https://maps.googleapis.com/maps/api/js?key=' + encodeURIComponent(els[0].getAttribute('data-key')) +
            '&loading=async&callback=lswInitMaps';
    s.async = true;
    document.head.appendChild(s);
  }

  function init() {
    stickyHeaders();
    Array.prototype.forEach.call(document.querySelectorAll('[data-lsw-carousel]'), carousel);
    maps();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
